WITH ended_lessons AS (SELECT school_uid,course_id,class_id FROM eo_pdviews.ods_ms_eo_os_eeo_course_class_di_view WHERE dt>='2026-09-05' AND dt<='2026-09-11' AND class_btime>=1788537600 AND class_btime<1789142400 AND class_status=3 AND school_uid>0 GROUP BY school_uid,course_id,class_id),
course_frame AS (SELECT a.school_uid,a.course_id,a.category_id,COUNT(DISTINCT l.class_id) AS opened_n FROM eo_pdviews.ods_ms_eo_oslms_lms_activity_df_view a JOIN ended_lessons l ON a.school_uid=l.school_uid AND a.course_id=l.course_id AND a.biz_id=l.class_id WHERE a.dt='2026-09-11' AND a.biz_type=1 AND a.is_deleted=0 AND a.publish_flag=2 AND a.category_id>0 AND a.start_time>=1788537600 AND a.start_time<1789142400 GROUP BY a.school_uid,a.course_id,a.category_id), pa AS (SELECT a.id,a.biz_id,a.school_uid,a.course_id,a.category_id,a.student_total FROM eo_pdviews.ods_ms_eo_oslms_lms_activity_df_view a JOIN course_frame f ON a.school_uid=f.school_uid AND a.course_id=f.course_id AND a.category_id=f.category_id WHERE a.dt='2026-09-11' AND a.biz_type=2 AND a.is_deleted=0 AND a.publish_flag=2 AND a.start_time<1789142400 AND (a.end_time=0 OR a.end_time>=1788537600)) SELECT MIN(h.homework_id) AS min_homework_id,MAX(h.homework_id) AS max_homework_id,COUNT(DISTINCT h.homework_id) AS homework_n FROM pa a JOIN eo_pdviews.ods_ms_eo_oshw_eeo_course_homework_7df_view h ON a.biz_id=h.homework_id AND a.school_uid=h.school_uid AND a.course_id=h.course_id WHERE h.dt='2026-09-11' AND h.is_del=0 AND h.start_time>=1788537600 AND h.start_time<1789142400
